from itertools import combinations, product
import heapq


def quota_intervals(capacity, tie):
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best_value = None
        best_ids = None
        for subset in combinations([j for j in jobs if j["id"] not in blocked], k):
            ids = tuple(sorted(j["id"] for j in subset))
            if not mandatory.issubset(ids):
                continue
            counts = {}
            for job in subset:
                group = job["group"]
                counts[group] = counts.get(group, 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            active = []
            valid = True
            for job in sorted(subset, key=lambda j: (j["start"], j["end"], j["id"])):
                active = [end for end in active if end > job["start"]]
                active.append(job["end"])
                if len(active) > capacity:
                    valid = False
                    break
            if not valid:
                continue
            value = sum(j["value"] for j in subset)
            if (best_value is None or value > best_value or
                (value == best_value and
                 ((tie == "smallest" and ids < best_ids) or
                  (tie == "largest" and ids > best_ids)))):
                best_value, best_ids = value, ids
        if best_value is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


def component_06(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(data["events"]):
        seq = event.get("sequence", 0)
        if seq > cutoff:
            continue
        ident = ("id", event["id"]) if "id" in event else ("anonymous", pos)
        key = (seq, event.get("revision", 0), pos)
        if ident not in winners or key > winners[ident][0]:
            winners[ident] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    def rounded(n, d):
        return n // d if mode == "floor" else (2 * n + d) // (2 * d)

    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000)
        tax = rounded(net * event.get("tax_bp", 0), 10000)
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def component_07(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    rows = {}
    domains = {}
    for name in names:
        by_version = {row["version"]: row for row in packages[name]}
        rows[name] = by_version
        domains[name] = [None] + [v for v in sorted(by_version)
                                  if v not in blocked.get(name, []) and
                                  (name not in pins or pins[name] == v)]

    best_vec = None
    best = None
    for values in product(*(domains[name] for name in names)):
        chosen = dict(zip(names, values))
        if any(chosen.get(name) is None or
               not low <= chosen[name] <= high
               for name, (low, high) in roots.items()):
            continue
        edges = {name: [] for name in names if chosen[name] is not None}
        valid = True
        for name, version in chosen.items():
            if version is None:
                continue
            for dep in rows[name][version].get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                v = chosen.get(other)
                if v is None or not dep["min"] <= v <= dep["max"]:
                    valid = False
                    break
                edges[name].append(other)
            if not valid:
                break
        if not valid:
            continue
        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            if chosen.get(name) is None:
                valid = False
                break
            reachable.add(name)
            stack.extend(edges[name])
        if not valid or reachable != set(edges):
            continue
        done, active = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in done:
                return True
            active.add(name)
            if any(not visit(other) for other in edges[name]):
                return False
            active.remove(name)
            done.add(name)
            return True
        if not all(visit(name) for name in edges):
            continue
        vec = tuple(-1 if chosen[name] is None else chosen[name] for name in names)
        if best_vec is None or vec > best_vec:
            best_vec = vec
            best = {name: chosen[name] for name in names if chosen[name] is not None}
    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best}


def component_08(data):
    required = data.get("required", [])
    full = (1 << len(required)) - 1
    initial_mask = sum(1 << i for i, node in enumerate(required)
                       if node == data["source"])
    start_state = (data["source"], initial_mask, data["coupons"])
    distances = {start_state: data["start"]}
    queue = [(data["start"],) + start_state]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full and remaining == 0:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            choices = [(edge["duration"], remaining)]
            if remaining:
                choices.append((max(2, edge["duration"] - edge.get("discount", 0)), remaining - 1))
            for duration, left in choices:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                nxt = edge["v"]
                new_mask = mask | sum(1 << i for i, n in enumerate(required) if n == nxt)
                new_state = (nxt, new_mask, left)
                if arrival < distances.get(new_state, float("inf")):
                    distances[new_state] = arrival
                    heapq.heappush(queue, (arrival,) + new_state)
    return {"arrival": None}


SOLVERS = {
    "component_01": quota_intervals(2, "smallest"),
    "component_02": quota_intervals(1, "largest"),
    "component_03": quota_intervals(2, "largest"),
    "component_04": quota_intervals(1, "smallest"),
    "component_05": quota_intervals(2, "smallest"),
    "component_06": component_06,
    "component_07": component_07,
    "component_08": component_08,
}
